<?php
namespace App\Filament\Resources\DiscordGuildResource\Pages; use App\Filament\Resources\DiscordGuildResource; use App\Services\DiscordGuildSyncService; use Filament\Actions; use Filament\Notifications\Notification; use Filament\Resources\Pages\EditRecord; use Throwable;
class EditDiscordGuild extends EditRecord {protected static string $resource=DiscordGuildResource::class; protected function getHeaderActions():array{return [Actions\Action::make('syncDiscord')->label('Synchroniser Discord')->icon('heroicon-o-arrow-path')->action(function(): void {try{app(DiscordGuildSyncService::class)->sync($this->record);Notification::make()->title('Serveur synchronisé')->success()->send();}catch(Throwable $error){Notification::make()->title('Synchronisation impossible')->body($error->getMessage())->danger()->send();}}),Actions\DeleteAction::make()];}}
